// Package webui embeds the built frontend so the standalone server and the
// desktop shell serve identical assets. The dist directory is generated by
// `npm run build --prefix frontend` (outDir points here); it is not committed.
package webui

import (
	"embed"
	"io/fs"
)

//go:embed all:dist
var dist embed.FS

// Assets returns the embedded frontend root as an fs.FS.
func Assets() (fs.FS, error) {
	return fs.Sub(dist, "dist")
}
